      "i": 0,
      "speaker": "bot",
      "text": "Hello Pawan, आपको semi-automatic cotton wick making machine की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "मैं देख पा रही हूं।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "आपको automation grade automatic ही चाहिए ना?"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "नहीं madam थोड़ा वो sales भी होना चाहिए।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "semi automatic है।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "आधा sales automatic हो आधा manual भी हो।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "ठीक है समझ गई।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "अब बताइए big type में क्या prefer करेंगे round, long या कोई और?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "जो गोल गोल बत्ती होती है ना।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "ठीक है आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "जी Madam."
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "आपका भी madam good morning, खुश रहिए।"
    }
